{
  "status": "STABLE",
  "core_findings": [
    "Measured numerical controls passed, with readout errors at most 9.54e-7 and zero reported batch-consistency and bounded-future errors. This supports stability within the tested conditions only.",
    "Ungated training sensitivity differs by category: interior permutation reduced diagnostic HR@10 most clearly in CDs_and_Vinyl, while endpoint replacement had its clearest effect in Industrial_and_Scientific. Numerically gated intermediate restoration and disruption showed corresponding directional effects relative to their separate recipients."
  ],
  "key_implications": [
    "The selected training predictions depend differently on earlier ordering and the latest item across categories; endpoint dependence does not establish shortcut learning.",
    "Single-position patches show conditional intermediate sensitivity, without establishing universal necessity, sufficiency or causal locality; matched-donor coverage was zero.",
    "Host validation performance, export parity and complete dependency paths remain unverified; bootstrap intervals exclude training, search and candidate/corruption sampling uncertainty, and replay manifest writing failed."
  ],
  "evidence": {
    "headline_metrics": {
      "CDs_ordering_HR10_delta": -0.15625,
      "CDs_ordering_HR10_95_interval": [-0.27083, -0.0625],
      "Industrial_endpoint_HR10_delta": -0.1875,
      "Industrial_endpoint_HR10_95_interval": [-0.33333, -0.05208],
      "CDs_blocks4_ordering_restoration_HR10_delta": 0.14583,
      "CDs_blocks4_ordering_disruption_HR10_delta": -0.125,
      "matched_donor_eligible_recipients_per_category": 0
    },
    "brief_metric_read": {
      "input_deltas": "Corrupted minus clean, user-weighted across 32 selected training users per category; diagnostic candidates only.",
      "patch_deltas": "Patched minus each direction's own recipient, conditional on numerical gating; restoration and disruption are distinct comparisons.",
      "uncertainty": "Intervals are conditional and lack simultaneous guarantees; four-category host validation uncertainty is unavailable."
    }
  }
}
